// ═══════════════════════════════════════════════════════════════
// HOLU — Agente de pedidos por WhatsApp
//
// Todo el loop del agente vive en este único nodo (parseo del mensaje,
// resolución de restaurante, memoria de la conversación, llamadas a
// Claude, ejecución de herramientas y respuesta por WhatsApp) para
// minimizar la cantidad de nodos que hay que cablear a mano en el
// editor de n8n. El checkout reutiliza el webhook delivery-checkout
// que ya existe — el pedido de WhatsApp entra a cocina por el mismo
// camino que un pedido de la página de delivery.
// ═══════════════════════════════════════════════════════════════

const SUPABASE_URL = 'https://nlwrkumlrudfgsdnhfhw.supabase.co';
const SERVICE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const ANTHROPIC_KEY = $env.ANTHROPIC_API_KEY;
const N8N_BASE = ($env.N8N_PUBLIC_URL || '').replace(/\/+$/, '');
const EVOLUTION_URL = ($env.EVOLUTION_API_URL || '').replace(/\/+$/, '');
const EVOLUTION_KEY = $env.EVOLUTION_API_KEY;

const input = $input.first().json;
const body = input.body ?? input;

// ── 1. Parse the Evolution API inbound payload ──────────────────────
const data = body.data || {};
const keyInfo = data.key || {};
const msg = data.message || {};
const remoteJid = keyInfo.remoteJid || '';
const phone = remoteJid.split('@')[0];
const text = (msg.conversation || msg.extendedTextMessage?.text || '').trim();
const instance = body.instance || '';
const pushName = data.pushName || 'Cliente';

if (keyInfo.fromMe || !text || !phone || !instance) {
  return [{ json: { skip: true, reason: 'not-a-customer-text-message' } }];
}

const supaHeaders = {
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json',
};

async function supaGet(path) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, { headers: supaHeaders });
  if (!res.ok) throw new Error(`supabase GET ${path} -> ${res.status}`);
  return res.json();
}
async function supaWrite(path, method, payload, prefer = 'return=representation') {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    method,
    headers: { ...supaHeaders, Prefer: prefer },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(`supabase ${method} ${path} -> ${res.status}`);
  return prefer.includes('return=minimal') ? null : res.json();
}

// ── 2. Resolve which restaurant owns this WhatsApp instance ─────────
const restRows = await supaGet(
  `restaurants?select=id,name,settings&settings->whatsapp_agent->>evolution_instance=eq.${encodeURIComponent(instance)}&settings->whatsapp_agent->>enabled=eq.true&limit=1`
);
const restaurant = restRows[0];
if (!restaurant) {
  return [{ json: { skip: true, reason: 'no-restaurant-for-instance', instance } }];
}
const restaurantId = restaurant.id;
const waCfg = restaurant.settings?.whatsapp_agent || {};
const deliveryCfg = restaurant.settings?.delivery || {};

// ── 3. Load or create the session (one per restaurant + phone) ──────
let sessionRows = await supaGet(
  `whatsapp_sessions?restaurant_id=eq.${restaurantId}&phone=eq.${encodeURIComponent(phone)}&limit=1`
);
let session = sessionRows[0];
if (!session) {
  const created = await supaWrite('whatsapp_sessions', 'POST', {
    restaurant_id: restaurantId, phone, customer_name: pushName,
    messages: [], cart: [], status: 'active',
  });
  session = created[0];
}

// ── 4. Fetch the live menu — the only source of truth for names/prices
const menu = await supaGet(
  `menu_items?restaurant_id=eq.${restaurantId}&available=eq.true&visible_client=eq.true&select=id,name,category,price,subtitle&order=category.asc,name.asc`
);

// ── 5. Tools the agent can call ──────────────────────────────────────
const tools = [
  {
    name: 'add_item',
    description: 'Agrega un plato al pedido del cliente. Usa el id exacto del menú.',
    input_schema: {
      type: 'object',
      properties: { menu_item_id: { type: 'string' }, qty: { type: 'integer', minimum: 1 } },
      required: ['menu_item_id', 'qty'],
    },
  },
  {
    name: 'remove_item',
    description: 'Quita o reduce la cantidad de un plato del pedido.',
    input_schema: {
      type: 'object',
      properties: { menu_item_id: { type: 'string' }, qty: { type: 'integer', minimum: 1 } },
      required: ['menu_item_id'],
    },
  },
  {
    name: 'view_cart',
    description: 'Devuelve el resumen del pedido actual con el total.',
    input_schema: { type: 'object', properties: {} },
  },
  {
    name: 'checkout',
    description: 'Confirma el pedido y genera el link de pago de MercadoPago. Solo úsala cuando el cliente ya confirmó qué quiere pedir y ya diste su nombre y dirección de entrega.',
    input_schema: {
      type: 'object',
      properties: {
        customer_name: { type: 'string' },
        address: { type: 'string' },
        address_notes: { type: 'string' },
      },
      required: ['customer_name', 'address'],
    },
  },
  {
    name: 'escalate_human',
    description: 'Avisa a un encargado humano del restaurante cuando no puedes resolver algo (reclamo, pregunta rara, pedido especial fuera de la carta).',
    input_schema: {
      type: 'object',
      properties: { reason: { type: 'string' } },
      required: ['reason'],
    },
  },
];

function cartTotal(cart) { return cart.reduce((s, i) => s + i.unit_price * i.qty, 0); }
function cartSummaryText(cart) {
  if (cart.length === 0) return 'El carrito está vacío.';
  const fee = Number(deliveryCfg.fee || 0);
  const subtotal = cartTotal(cart);
  const lines = cart.map((i) => `${i.qty}x ${i.name} - $${(i.unit_price * i.qty).toLocaleString('es-CL')}`);
  lines.push(`Envío: $${fee.toLocaleString('es-CL')}`);
  lines.push(`Total: $${(subtotal + fee).toLocaleString('es-CL')}`);
  return lines.join('\n');
}

async function runTool(name, toolInput, cart) {
  if (name === 'add_item') {
    const menuItem = menu.find((m) => m.id === toolInput.menu_item_id);
    if (!menuItem) return { error: 'Ese plato no existe en la carta actual.' };
    const qty = Math.max(1, Math.min(20, parseInt(toolInput.qty, 10) || 1));
    const existing = cart.find((c) => c.menu_item_id === menuItem.id);
    if (existing) existing.qty += qty;
    else cart.push({ menu_item_id: menuItem.id, name: menuItem.name, unit_price: menuItem.price, qty });
    return { ok: true, cart: cartSummaryText(cart) };
  }
  if (name === 'remove_item') {
    const idx = cart.findIndex((c) => c.menu_item_id === toolInput.menu_item_id);
    if (idx === -1) return { error: 'Ese plato no está en el carrito.' };
    const qty = toolInput.qty ? parseInt(toolInput.qty, 10) : cart[idx].qty;
    cart[idx].qty -= qty;
    if (cart[idx].qty <= 0) cart.splice(idx, 1);
    return { ok: true, cart: cartSummaryText(cart) };
  }
  if (name === 'view_cart') {
    return { cart: cartSummaryText(cart) };
  }
  if (name === 'checkout') {
    if (cart.length === 0) return { error: 'El carrito está vacío, no se puede pagar.' };
    try {
      const res = await fetch(`${N8N_BASE}/webhook/delivery-checkout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          restaurant_id: restaurantId,
          customer_name: toolInput.customer_name,
          phone,
          address: toolInput.address,
          address_notes: toolInput.address_notes || null,
          items: cart.map((c) => ({ menu_item_id: c.menu_item_id, qty: c.qty })),
        }),
      });
      const resData = await res.json().catch(() => null);
      if (!res.ok || !resData?.init_point) {
        return { error: resData?.message || 'No se pudo generar el link de pago. Intenta de nuevo en un momento.' };
      }
      cart.length = 0;
      return { ok: true, payment_link: resData.init_point };
    } catch (e) {
      return { error: 'No se pudo conectar con el sistema de pago.' };
    }
  }
  if (name === 'escalate_human') {
    try {
      await supaWrite('calls', 'POST', {
        id: `WA-${Math.random().toString(36).slice(2, 8).toUpperCase()}`,
        restaurant_id: restaurantId,
        source: 'whatsapp',
        call_type: 'Otro',
        priority: 'Alta',
        status: 'Pendiente',
        message: `WhatsApp ${phone}: ${toolInput.reason || 'necesita ayuda'}`,
      }, 'return=minimal');
    } catch (e) {}
    return { ok: true, message: 'Un encargado del restaurante va a escribirte pronto.' };
  }
  return { error: `Tool desconocida: ${name}` };
}

// ── 6. System prompt ──────────────────────────────────────────────
const menuText = menu.map((m) => `- [${m.id}] ${m.name} (${m.category || 'Carta'}) — $${m.price.toLocaleString('es-CL')}${m.subtitle ? ' — ' + m.subtitle : ''}`).join('\n');
const personality = waCfg.personality ? `Tono: ${waCfg.personality}.` : 'Tono: cercano, breve, claro.';

const systemPrompt = `Eres el agente de pedidos por WhatsApp de "${restaurant.name}". ${personality}
Tu único trabajo es ayudar al cliente a armar su pedido y pagarlo. No inventes platos ni precios: usa exactamente los de esta carta.

CARTA ACTUAL:
${menuText || '(la carta está vacía por ahora)'}

Reglas:
- Usa add_item/remove_item para ir armando el pedido a medida que el cliente lo pide.
- Antes de cobrar, confirma en texto qué lleva el pedido y el total.
- Para cobrar (checkout) necesitas nombre y dirección de entrega — pídelos si no los tienes.
- Después de un checkout exitoso, manda el link de pago tal cual lo recibas y avisa que el pedido entra a cocina apenas se confirme el pago.
- Si el cliente pide algo que no puedes resolver (reclamos, pedidos muy especiales, algo raro), usa escalate_human y avísale que alguien del restaurante lo va a contactar.
- Nunca digas que un pedido ya está confirmado si checkout no te devolvió un link de pago.`;

// ── 7. Agentic loop ───────────────────────────────────────────────
let cart = Array.isArray(session.cart) ? session.cart.map((c) => ({ ...c })) : [];
let messages = Array.isArray(session.messages) ? [...session.messages] : [];
messages.push({ role: 'user', content: text });

let finalText = '';
const MAX_ITER = 5;
for (let i = 0; i < MAX_ITER; i++) {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'x-api-key': ANTHROPIC_KEY,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model: 'claude-sonnet-5',
      max_tokens: 1024,
      system: systemPrompt,
      tools,
      messages,
    }),
  });
  if (!res.ok) {
    finalText = 'Uy, tuve un problema técnico. Intenta de nuevo en un ratito.';
    break;
  }
  const claude = await res.json();
  messages.push({ role: 'assistant', content: claude.content });

  if (claude.stop_reason !== 'tool_use') {
    finalText = (claude.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n');
    break;
  }

  const toolResults = [];
  for (const block of claude.content) {
    if (block.type !== 'tool_use') continue;
    const result = await runTool(block.name, block.input, cart);
    toolResults.push({ type: 'tool_result', tool_use_id: block.id, content: JSON.stringify(result) });
  }
  messages.push({ role: 'user', content: toolResults });

  if (i === MAX_ITER - 1) finalText = 'Dame un segundo más para confirmarte esto — ¿me repites qué necesitabas?';
}

// ── 8. Send the reply over WhatsApp ───────────────────────────────
if (EVOLUTION_URL && EVOLUTION_KEY) {
  await fetch(`${EVOLUTION_URL}/message/sendText/${instance}`, {
    method: 'POST',
    headers: { apikey: EVOLUTION_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ number: phone, text: finalText }),
  }).catch(() => {});
}

// ── 9. Persist the session (cap history so it never grows unbounded)
await supaWrite(`whatsapp_sessions?id=eq.${session.id}`, 'PATCH', {
  messages: messages.slice(-40),
  cart,
  customer_name: pushName,
}, 'return=minimal');

return [{ json: { ok: true, restaurant_id: restaurantId, phone, reply: finalText } }];
